<script lang="ts">let {days=[]}:{days?:string[]}=$props();let now=new Date();let monday=new Date(now);monday.setDate(now.getDate()-((now.getDay()+6)%7));</script><ol class="week-dots" aria-label="This week">{#each ['M','T','W','T','F','S','S'] as day,i}{@const date=new Date(monday.getFullYear(),monday.getMonth(),monday.getDate()+i).toLocaleDateString('en-CA')}<li class:done={days.includes(date)} class:today={i===(now.getDay()+6)%7}>{day}</li>{/each}</ol>
